import java.util.*;
public class Main {
    static class Node { int k, v; Node prev, next; Node(int k,int v){this.k=k;this.v=v;} }
    static class LRUCache {
        private final int cap; private final Map<Integer,Node> map = new HashMap<>();
        private final Node head = new Node(0,0), tail = new Node(0,0);
        LRUCache(int c){ cap=c; head.next=tail; tail.prev=head; }
        private void remove(Node n){ n.prev.next=n.next; n.next.prev=n.prev; }
        private void toHead(Node n){ n.next=head.next; n.next.prev=n; n.prev=head; head.next=n; }
        public int get(int k){ Node n=map.get(k); if(n==null) return -1; remove(n); toHead(n); return n.v; }
        public void put(int k,int v){ Node n=map.get(k); if(n!=null){ n.v=v; remove(n); toHead(n); return; } n=new Node(k,v); map.put(k,n); toHead(n); if(map.size()>cap){ Node t=tail.prev; remove(t); map.remove(t.k); } }
    }
    public static void main(String[] args){
        LRUCache c=new LRUCache(2);
        c.put(1,1); c.put(2,2);
        System.out.println(c.get(1)); c.put(3,3);
        System.out.println(c.get(2)); c.put(4,4);
        System.out.println(c.get(1)); System.out.println(c.get(3)); System.out.println(c.get(4));
    }
}

import java.util.*;
public class Main {
    static class MyQueue {
        private final Deque<Integer> in = new ArrayDeque<>();
        private final Deque<Integer> out = new ArrayDeque<>();
        public void push(int x){ in.push(x); }
        private void drain(){ if(out.isEmpty()) while(!in.isEmpty()) out.push(in.pop()); }
        public int pop(){ drain(); return out.pop(); }
        public int peek(){ drain(); return out.peek(); }
        public boolean empty(){ return in.isEmpty() && out.isEmpty(); }
    }
    public static void main(String[] args){
        MyQueue q=new MyQueue();
        q.push(1); q.push(2);
        System.out.println(q.peek()); System.out.println(q.pop()); System.out.println(q.empty());
    }
}
